DATA = "diff --git a/CHANGELOG.md b/CHANGELOG.md\nindex 8a91427..37fe1ad 100644\n--- a/CHANGELOG.md\n+++ b/CHANGELOG.md\n@@ -4,6 +4,7 @@\n \n ### Added\n \n+- Browser: persist ChatGPT assistant sandbox-linked downloadable files when a matching trusted backend download anchor is available; record file metadata and block auto-archive when downloads are incomplete.\n - Browser: `oracle session <id> --harvest` and `--live` now auto-recover when the original Chrome has been closed by relaunching the manual-login profile and reopening the saved conversation URL, then retrying the harvest against the recovered tab. Resolves the failure mode where a long GPT-5 Pro Extended response completed in the background after the CLI's 20-minute wall expired and the conversation was archived. Recovery URL selection prefers `browser.harvest.url` over `browser.runtime.tabUrl` and is gated by a shared ChatGPT-conversation-URL check (rejects home, project shell, and external URLs so the persistent profile can't be navigated to the wrong page from stale metadata). Opt out with `--no-recover` on the `session` subcommand.\n \n ## 0.13.0 — 2026-05-22\ndiff --git a/src/browser/chatgptFiles.ts b/src/browser/chatgptFiles.ts\nnew file mode 100644\nindex 0000000..d85efd9\n--- /dev/null\n+++ b/src/browser/chatgptFiles.ts\n@@ -0,0 +1,209 @@\n+/** Capture downloadable ChatGPT assistant files without trusting model-authored URLs. */\n+import fs from \"node:fs/promises\";\n+import path from \"node:path\";\n+import type { SessionArtifact } from \"../sessionStore.js\";\n+import type { BrowserLogger, ChromeClient } from \"./types.js\";\n+import { resolveSessionArtifactsDir } from \"./artifacts.js\";\n+import { ASSISTANT_ROLE_SELECTOR, CONVERSATION_TURN_SELECTOR } from \"./constants.js\";\n+\n+const MAX_FILES = 20;\n+const MAX_FILE_BYTES = 100 * 1024 * 1024;\n+const MAX_REDIRECTS = 3;\n+const DOWNLOAD_TIMEOUT_MS = 30_000;\n+\n+export interface DownloadableFileLink {\n+  sourceUrl: string;\n+  downloadUrl?: string;\n+  filename: string;\n+  linkText?: string;\n+}\n+\n+/** Only ChatGPT backend endpoints may receive ChatGPT cookies. */\n+export function isTrustedChatGptDownloadUrl(value: string): boolean {\n+  try {\n+    const url = new URL(value);\n+    return url.protocol === \"https:\" && url.hostname === \"chatgpt.com\" &&\n+      url.port === \"\" && url.pathname.startsWith(\"/backend-api/\") &&\n+      !url.username && !url.password;\n+  } catch {\n+    return false;\n+  }\n+}\n+\n+function safeFilename(value: string): string {\n+  const leaf = value.replace(/\\\\/g, \"/\").split(\"/\").pop() ?? \"\";\n+  const safe = leaf.replace(/[\\x00-\\x1f\\x7f<>:\"|?*]/g, \"_\")\n+    .replace(/[^\\p{L}\\p{N}._() -]/gu, \"_\")\n+    .replace(/^\\.+/, \"\").trim().slice(0, 120);\n+  return safe && safe !== \".\" && safe !== \"..\" ? safe : \"download\";\n+}\n+\n+/** Accept only sandbox paths as sources, never arbitrary external markdown URLs. */\n+export function extractSandboxFileLinks(markdown: string): DownloadableFileLink[] {\n+  const result: DownloadableFileLink[] = [];\n+  const seen = new Set<string>();\n+  const regex = /\\[[^\\]\\n]*\\]\\((sandbox:\\/mnt\\/data\\/[^\\s)]+)(?:\\s+\"[^\"]*\")?\\)/g;\n+  for (const match of markdown.matchAll(regex)) {\n+    const sourceUrl = match[1];\n+    if (!sourceUrl || seen.has(sourceUrl)) continue;\n+    seen.add(sourceUrl);\n+    let filename: string;\n+    try { filename = safeFilename(decodeURIComponent(sourceUrl.split(\"/\").pop() ?? \"\")); }\n+    catch { filename = safeFilename(sourceUrl.split(\"/\").pop() ?? \"\"); }\n+    result.push({ sourceUrl, filename });\n+  }\n+  return result.slice(0, MAX_FILES);\n+}\n+\n+/** Read only anchors in assistant turns, scoped to the current response boundary. */\n+export async function readAssistantFileLinks(\n+  Runtime: ChromeClient[\"Runtime\"],\n+  minTurnIndex?: number | null,\n+): Promise<DownloadableFileLink[]> {\n+  const boundary = typeof minTurnIndex === \"number\" && Number.isFinite(minTurnIndex)\n+    ? Math.max(0, Math.floor(minTurnIndex)) : 0;\n+  const expression = `(() => {\n+    const turns = Array.from(document.querySelectorAll(${JSON.stringify(CONVERSATION_TURN_SELECTOR)}));\n+    const results = [];\n+    for (let i = ${boundary}; i < turns.length; i++) {\n+      const turn = turns[i];\n+      const role = (turn.getAttribute('data-message-author-role') || turn.getAttribute('data-turn') || '').toLowerCase();\n+      if (role !== 'assistant' && !turn.querySelector(${JSON.stringify(ASSISTANT_ROLE_SELECTOR)})) continue;\n+      const root = turn.querySelector(${JSON.stringify(ASSISTANT_ROLE_SELECTOR)}) || turn;\n+      for (const a of root.querySelectorAll('a[href]')) {\n+        const raw = a.getAttribute('href') || '';\n+        const displayed = a.textContent || '';\n+        const sourceUrl = raw.startsWith('sandbox:/mnt/data/') ? raw :\n+          (displayed.match(/sandbox:\\\\/mnt\\\\/data\\\\/[^\\\\s)]+/) || [])[0];\n+        const downloadUrl = a.href.startsWith('https://') ? a.href : undefined;\n+        if (!sourceUrl && !downloadUrl?.includes('/backend-api/')) continue;\n+        results.push({ sourceUrl: sourceUrl || '', downloadUrl, filename: a.getAttribute('download') || '', linkText: displayed.trim() });\n+      }\n+    }\n+    return results;\n+  })()`;\n+  const { result } = await Runtime.evaluate({ expression, returnByValue: true });\n+  return Array.isArray(result?.value) ? result.value.filter((link: unknown) =>\n+    typeof link === \"object\" && link !== null &&\n+    typeof (link as DownloadableFileLink).sourceUrl === \"string\") : [];\n+}\n+\n+async function fetchTrustedFile(url: string, cookieHeader: string): Promise<{ bytes: Buffer; mimeType: string }> {\n+  let current = url;\n+  const controller = new AbortController();\n+  const timer = setTimeout(() => controller.abort(), DOWNLOAD_TIMEOUT_MS);\n+  try {\n+    for (let redirects = 0; redirects <= MAX_REDIRECTS; redirects++) {\n+      if (!isTrustedChatGptDownloadUrl(current)) throw new Error(\"untrusted download origin or path\");\n+      const response = await fetch(current, {\n+        headers: { cookie: cookieHeader, \"user-agent\": \"Mozilla/5.0\" },\n+        redirect: \"manual\", signal: controller.signal,\n+      });\n+      if ([301, 302, 303, 307, 308].includes(response.status)) {\n+        const location = response.headers.get(\"location\");\n+        if (!location) throw new Error(\"redirect without Location\");\n+        current = new URL(location, current).href;\n+        continue;\n+      }\n+      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n+      const length = Number(response.headers.get(\"content-length\") ?? \"0\");\n+      if (!Number.isFinite(length) || length > MAX_FILE_BYTES) throw new Error(\"file too large\");\n+      const mimeType = (response.headers.get(\"content-type\") ?? \"application/octet-stream\").split(\";\")[0]!.trim();\n+      if (mimeType === \"text/html\" || mimeType === \"application/xhtml+xml\") {\n+        throw new Error(\"received HTML instead of a file\");\n+      }\n+      if (!response.body) throw new Error(\"empty respo"
